WITH flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT page, CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, COUNT(*) AS event_count, COUNT(*) AS row_count, SUM(CASE WHEN event_type = 'add_to_cart' THEN is_new_burst ELSE 0 END) AS add_to_cart_is_new_burst, PERCENTILE_APPROX(is_new_burst, ARRAY(0.25, 0.5, 0.75)) AS is_new_burst_quartiles FROM sessions_web_events GROUP BY 1, 2 HAVING row_count >= 1 ORDER BY row_count
